// Conteúdo de estudo por tema: cartões com pontos-chave e figuras próprias (SVG)
const TEMAS=[{"id": "nom", "nome": "Nomenclatura e estabilidade", "icone": "⚓", "cards": [{"t": "Bordos e marcações", "p": ["Olhando da popa para a proa: <b>boreste (BE)</b> à direita, luz verde; <b>bombordo (BB)</b> à esquerda, luz encarnada.", "Se você estiver na proa olhando para a popa, inverte: à sua direita fica <b>bombordo</b>.", "Marcação relativa conta em graus a partir da proa, no sentido horário: 090° é o través de BE, <b>180° é a popa</b>, 270° o través de BB.", "<b>Bochechas</b>: partes curvas do costado junto à proa. <b>Alhetas</b>: junto à popa."], "f": "<svg viewBox=\"0 0 320 230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><path d=\"M160,28 C206,66 214,112 208,188 L112,188 C106,112 114,66 160,28 Z\" fill=\"var(--card)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/><path d=\"M160,28 C206,66 214,112 210,112\" fill=\"none\" stroke=\"#0b8a4a\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M160,28 C114,66 106,112 110,112\" fill=\"none\" stroke=\"#cf2e3a\" stroke-width=\"6\" stroke-linecap=\"round\"/><line x1=\"112\" y1=\"112\" x2=\"208\" y2=\"112\" stroke=\"var(--muted)\" stroke-dasharray=\"4 4\"/><text x=\"160\" y=\"16\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">PROA · 000°</text><text x=\"160\" y=\"212\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">POPA · 180°</text><text x=\"222\" y=\"104\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"#0b8a4a\" text-anchor=\"start\">BORESTE</text><text x=\"222\" y=\"120\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#0b8a4a\" text-anchor=\"start\">BE · 090°</text><text x=\"98\" y=\"104\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"#cf2e3a\" text-anchor=\"end\">BOMBORDO</text><text x=\"98\" y=\"120\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#cf2e3a\" text-anchor=\"end\">BB · 270°</text><text x=\"232\" y=\"62\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"start\">bochecha</text><text x=\"88\" y=\"62\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"end\">bochecha</text><text x=\"226\" y=\"180\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"start\">alheta</text><text x=\"94\" y=\"180\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"end\">alheta</text><text x=\"160\" y=\"108\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">través</text><text x=\"160\" y=\"150\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">meia-nau</text><path d=\"M160,170 L160,135\" stroke=\"var(--ink)\" stroke-width=\"2\" marker-end=\"url(#ar)\"/><defs><marker id=\"ar\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 Z\" fill=\"var(--ink)\"/></marker></defs><text x=\"160\" y=\"226\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">olhando da popa para a proa: BE à direita, BB à esquerda</text></svg>"}, {"t": "Medidas do casco", "p": ["<b>Calado</b>: da linha d'água até a parte mais baixa (quilha).", "<b>Borda livre</b>: da linha d'água até o convés.", "<b>Pontal</b>: do convés principal até a quilha. É a única medida que <b>não muda</b> com a carga (calado, borda livre e deslocamento mudam).", "Obras vivas ficam abaixo da linha d'água; obras mortas, acima."], "f": "<svg viewBox=\"0 0 320 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><path d=\"M70,50 L250,50 L240,120 C228,170 192,182 160,186 C128,182 92,170 80,120 Z\" fill=\"var(--card)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/><path d=\"M30,105 q15,-6 30,0 t30,0 t30,0 t30,0 t30,0 t30,0 t30,0 t30,0 t30,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2.5\"/><path d=\"M78,108 L242,108 L240,120 C228,170 192,182 160,186 C128,182 92,170 80,120 Z\" fill=\"#2563a8\" fill-opacity=\".14\"/><text x=\"160\" y=\"84\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">obras mortas</text><text x=\"160\" y=\"150\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">obras vivas</text><text x=\"160\" y=\"44\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">convés</text><g stroke=\"var(--ink)\" stroke-width=\"1.5\"><line x1=\"268\" y1=\"50\" x2=\"268\" y2=\"105\"/><line x1=\"262\" y1=\"50\" x2=\"274\" y2=\"50\"/><line x1=\"262\" y1=\"105\" x2=\"274\" y2=\"105\"/><line x1=\"290\" y1=\"105\" x2=\"290\" y2=\"186\"/><line x1=\"284\" y1=\"186\" x2=\"296\" y2=\"186\"/><line x1=\"284\" y1=\"105\" x2=\"296\" y2=\"105\"/><line x1=\"48\" y1=\"50\" x2=\"48\" y2=\"186\"/><line x1=\"42\" y1=\"50\" x2=\"54\" y2=\"50\"/><line x1=\"42\" y1=\"186\" x2=\"54\" y2=\"186\"/><line x1=\"48\" y1=\"186\" x2=\"160\" y2=\"186\" stroke-dasharray=\"3 3\"/><line x1=\"160\" y1=\"186\" x2=\"290\" y2=\"186\" stroke-dasharray=\"3 3\"/></g><text x=\"272\" y=\"40\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">borda livre</text><text x=\"300\" y=\"150\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"end\">calado</text><text x=\"34\" y=\"122\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\" transform=\"rotate(-90 34 122)\">pontal</text><text x=\"160\" y=\"202\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">quilha</text></svg>"}, {"t": "Partes e vento", "p": ["<b>Casco</b>: o corpo da embarcação sem mastreação nem acessórios.", "<b>Bico de proa</b>: a ponta extrema da proa. Roda de proa é a peça que sobe da quilha na proa. <b>Cadaste</b> fica na popa.", "São partes da embarcação: <b>convés, costado e quilha</b> (trim, banda e calado são condições ou medidas).", "<b>Barlavento</b>: o lado de onde vem o vento. <b>Sotavento</b>: o lado para onde ele vai."]}, {"t": "Estabilidade", "p": ["A estabilidade piora com peso <b>em partes altas</b> ou <b>concentrado nas laterais</b>.", "<b>Contra-alquebramento</b>: muito peso a meia-nau e pouco nas pontas; o barco pode quebrar ao meio no mau tempo.", "O tempo para afundar depende da <b>reserva de flutuabilidade</b> e da <b>extensão da avaria</b>."]}]}, {"id": "rip", "nome": "RIPEAM: luzes, marcas e sons", "icone": "💡", "cards": [{"t": "Luzes de navegação", "p": ["Acenda do pôr ao nascer do sol e em <b>visibilidade restrita</b>. Atracado no cais não precisa.", "<b>Mastro</b>: branca, 225°, da proa até 22,5° por ante-a-ré do través.", "<b>Bordos</b>: verde a BE e encarnada a BB, 112,5° cada.", "<b>Alcançado</b>: branca na popa, 135°. Lancha comum: luz de mastro + bordos (ou lanterna combinada) + alcançado."], "f": "<svg viewBox=\"0 0 320 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><path d=\"M160,128 L63.9,167.8 A104,104 0 1 1 256.1,167.8 Z\" fill=\"#f4f1e6\" fill-opacity=\"1\" stroke=\"var(--muted)\" stroke-width=\"1.5\"/><path d=\"M160,128 L160.0,54.0 A74,74 0 0 1 228.4,156.3 Z\" fill=\"#0b8a4a\" fill-opacity=\"0.85\" stroke=\"none\" stroke-width=\"1.5\"/><path d=\"M160,128 L91.6,156.3 A74,74 0 0 1 160.0,54.0 Z\" fill=\"#cf2e3a\" fill-opacity=\"0.85\" stroke=\"none\" stroke-width=\"1.5\"/><path d=\"M160,128 L228.4,156.3 A74,74 0 0 1 91.6,156.3 Z\" fill=\"#d9d4c4\" fill-opacity=\"1\" stroke=\"var(--muted)\" stroke-width=\"1.5\"/><path d=\"M160,106 C170,116 170,132 169,148 L151,148 C150,132 150,116 160,106 Z\" fill=\"var(--ink)\"/><text x=\"160\" y=\"14\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">luz de MASTRO · branca · 225°</text><text x=\"316\" y=\"50\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"#0b8a4a\" text-anchor=\"end\">BE verde</text><text x=\"316\" y=\"66\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#0b8a4a\" text-anchor=\"end\">112,5°</text><text x=\"4\" y=\"50\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"#cf2e3a\" text-anchor=\"start\">BB encarnada</text><text x=\"4\" y=\"66\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#cf2e3a\" text-anchor=\"start\">112,5°</text><text x=\"160\" y=\"222\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">luz de ALCANÇADO · branca · 135°</text><text x=\"160\" y=\"240\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">(67,5° para cada bordo, a partir da popa)</text></svg>"}, {"t": "Luzes especiais", "p": ["<b>Fundeada</b>: luz circular branca onde melhor possa ser vista. Iluminar o convés é opcional.", "Veleiro com menos de 20 m pode usar uma <b>lanterna combinada no tope do mastro</b>.", "Veleiro que usa encarnada sobre verde no mastro <b>não</b> usa também a lanterna combinada.", "<b>Três luzes verdes em triângulo</b>: remoção de minas.", "Luz encarnada forte (pirotécnico) à noite: <b>embarcação em perigo</b>, pedindo auxílio."]}, {"t": "Marcas de dia", "p": ["As marcas (esferas, cones, cilindros) são sempre <b>pretas</b>.", "1 esfera: fundeada. 2 esferas: sem governo. 3 esferas: encalhada. Cilindro: manobra restrita pelo calado.", "Balão preto <b>não</b> é sinal de perigo, é embarcação fundeada."], "f": "<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><line x1=\"45\" y1=\"22\" x2=\"45\" y2=\"150\" stroke=\"var(--muted)\" stroke-width=\"3\"/><circle cx=\"45\" cy=\"40\" r=\"11\" fill=\"#1d2733\"/><line x1=\"125\" y1=\"22\" x2=\"125\" y2=\"150\" stroke=\"var(--muted)\" stroke-width=\"3\"/><circle cx=\"125\" cy=\"40\" r=\"11\" fill=\"#1d2733\"/><circle cx=\"125\" cy=\"66\" r=\"11\" fill=\"#1d2733\"/><line x1=\"205\" y1=\"22\" x2=\"205\" y2=\"150\" stroke=\"var(--muted)\" stroke-width=\"3\"/><circle cx=\"205\" cy=\"40\" r=\"11\" fill=\"#1d2733\"/><circle cx=\"205\" cy=\"66\" r=\"11\" fill=\"#1d2733\"/><circle cx=\"205\" cy=\"92\" r=\"11\" fill=\"#1d2733\"/><line x1=\"280\" y1=\"22\" x2=\"280\" y2=\"150\" stroke=\"var(--muted)\" stroke-width=\"3\"/><rect x=\"269\" y=\"30\" width=\"22\" height=\"34\" rx=\"3\" fill=\"#1d2733\"/><text x=\"45\" y=\"172\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">fundeada</text><text x=\"125\" y=\"172\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">sem governo</text><text x=\"205\" y=\"172\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">encalhada</text><text x=\"280\" y=\"172\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">restrita</text><text x=\"280\" y=\"188\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">pelo calado</text><text x=\"45\" y=\"188\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">1 esfera</text><text x=\"125\" y=\"188\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">2 esferas</text><text x=\"205\" y=\"188\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">3 esferas</text></svg>"}, {"t": "Sinais sonoros", "p": ["Sem apito, use <b>buzina ou sino</b>.", "Sinais de perigo: explosão a cada ~1 minuto, som contínuo de cerração, fumaça laranja, luz encarnada."], "h": "<table class=\"sons\"><tr><td><i class=\"c\"></i></td><td>estou guinando para <b>boreste</b></td></tr>\n<tr><td><i class=\"c\"></i><i class=\"c\"></i></td><td>estou guinando para <b>bombordo</b></td></tr>\n<tr><td><i class=\"c\"></i><i class=\"c\"></i><i class=\"c\"></i></td><td>estou <b>dando atrás</b> (máquina a ré)</td></tr>\n<tr><td><i class=\"c\"></i><i class=\"c\"></i><i class=\"c\"></i><i class=\"c\"></i><i class=\"c\"></i></td><td>5 ou mais curtos: <b>não entendi</b> sua manobra / dúvida</td></tr>\n<tr><td><i class=\"l\"></i><i class=\"l\"></i><i class=\"c\"></i></td><td>vou ultrapassar pelo seu <b>boreste</b></td></tr>\n<tr><td><i class=\"l\"></i><i class=\"l\"></i><i class=\"c\"></i><i class=\"c\"></i></td><td>vou ultrapassar pelo seu <b>bombordo</b></td></tr>\n<tr><td><i class=\"l\"></i><i class=\"c\"></i><i class=\"l\"></i><i class=\"c\"></i></td><td><b>concordo</b> com a ultrapassagem</td></tr>\n<tr><td><i class=\"l\"></i></td><td>chegando a <b>curva sem visibilidade</b>; quem ouve responde com 1 longo e reduz</td></tr>\n<tr><td><i class=\"l\"></i> <small>a cada 2 min</small></td><td>visibilidade restrita: <b>em movimento</b>, com seguimento</td></tr>\n<tr><td><i class=\"l\"></i><i class=\"l\"></i> <small>a cada 2 min</small></td><td>visibilidade restrita: <b>parada</b>, sem seguimento</td></tr></table>\n<p class=\"leg\"><i class=\"c\"></i> curto ≈ 1 s · <i class=\"l\"></i> longo 4 a 6 s</p>"}, {"t": "Regras de governo", "p": ["O RIPEAM existe para <b>evitar abalroamento no mar</b>, com regras de navegação, luzes, marcas e sons. Vale no mar aberto, nas águas ligadas a ele navegáveis por navios e nas águas interiores.", "<b>Rumos cruzados</b>: quem vê a outra pelo seu BB (vê a luz verde dela) tem preferência. Quem a vê por BE manobra.", "<b>Roda a roda</b>: as duas guinam para boreste.", "<b>Alcançadora</b> é quem chega por trás, mais rápida: ela manobra, não tem preferência. A alcançada mantém rumo e velocidade.", "Quem não tem preferência é a <b>obrigada a manobrar</b>. A outra é a <b>que tem preferência</b>, mas deve desviar se a outra não manobrar.", "Manobre de forma <b>franca, positiva e com antecedência</b>."]}, {"t": "Preferência e canais", "p": ["Ordem do gabarito: <b>sem governo</b> tem preferência sobre manobra restrita, pesca e vela. <b>Vela</b> tem preferência sobre motor.", "Em canal estreito, quem está pescando não pode atrapalhar quem navega no canal. Barco maior (mais de 20 m) tem preferência sobre o miúdo.", "Navio com manobra restrita pelo calado no canal: <b>só a lancha</b> se afasta e deixa o canal livre.", "Rio contra a correnteza: navegue junto à margem do <b>seu boreste</b>.", "\"Comprimento\" e \"boca\" no RIPEAM: de <b>roda a roda</b> e <b>largura máxima</b>."]}]}, {"id": "bal", "nome": "Balizamento", "icone": "🛟", "cards": [{"t": "Sinais laterais (IALA B)", "p": ["O Brasil usa o sistema <b>IALA B</b>: entrando do mar, deixe o <b>encarnado por boreste</b> e o verde por bombordo.", "Saindo para o mar inverte: luz encarnada fica por <b>bombordo</b>.", "Boreste: encarnada, tope em <b>cone</b>. Bombordo: verde, tope em <b>cilindro</b>.", "Canal preferencial a bombordo: luz <b>encarnada</b>."], "f": "<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><g transform=\"translate(90,40)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"48.5\" fill=\"#0b8a4a\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><rect x=\"-7\" y=\"-10\" width=\"14\" height=\"14\" fill=\"#0b8a4a\"/></g><g transform=\"translate(230,40)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"48.5\" fill=\"#cf2e3a\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><path d=\"M-9,4 L9,4 L0,-12 Z\" fill=\"#cf2e3a\"/></g><text x=\"90\" y=\"140\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"13\" fill=\"#0b8a4a\" text-anchor=\"middle\">BOMBORDO</text><text x=\"90\" y=\"156\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">verde · tope cilindro</text><text x=\"90\" y=\"170\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">luz verde</text><text x=\"230\" y=\"140\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"13\" fill=\"#cf2e3a\" text-anchor=\"middle\">BORESTE</text><text x=\"230\" y=\"156\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">encarnada · tope cone</text><text x=\"230\" y=\"170\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">luz encarnada</text><text x=\"160\" y=\"194\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">posição entrando do mar para o porto (IALA B, usado no Brasil)</text><path d=\"M160,130 L160,60\" stroke=\"var(--ink)\" stroke-width=\"2\" marker-end=\"url(#ar2)\"/><defs><marker id=\"ar2\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 Z\" fill=\"var(--ink)\"/></marker></defs><text x=\"160\" y=\"50\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">para o porto</text></svg>"}, {"t": "Sinais cardinais", "p": ["Preto e amarelo, com <b>dois cones</b> no tope. A luz é <b>branca</b>.", "O nome indica onde está a água segura: passe ao <b>norte</b> de uma cardinal norte, ao <b>sul</b> de uma cardinal sul.", "Boia preta com faixa amarela e cones <b>base com base</b>: cardinal leste."], "f": "<svg viewBox=\"0 0 320 305\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><circle cx=\"160\" cy=\"150\" r=\"22\" fill=\"none\" stroke=\"#cf2e3a\" stroke-width=\"2\" stroke-dasharray=\"4 3\"/><text x=\"160\" y=\"154\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"#cf2e3a\" text-anchor=\"middle\">PERIGO</text><g transform=\"translate(160,22)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"24.5\" fill=\"#1d2733\"/><rect x=\"-14\" y=\"44.0\" width=\"28\" height=\"24.5\" fill=\"#f2b531\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><path d=\"M-8,4 L8,4 L0,-8 Z\" fill=\"#1d2733\"/><path d=\"M-8,-10 L8,-10 L0,-22 Z\" fill=\"#1d2733\"/></g><text x=\"160\" y=\"108\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">NORTE ▲▲</text><g transform=\"translate(160,190)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"24.5\" fill=\"#f2b531\"/><rect x=\"-14\" y=\"44.0\" width=\"28\" height=\"24.5\" fill=\"#1d2733\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><path d=\"M-8,-6 L8,-6 L0,6 Z\" fill=\"#1d2733\"/><path d=\"M-8,-20 L8,-20 L0,-8 Z\" fill=\"#1d2733\"/></g><text x=\"160\" y=\"276\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">SUL ▼▼</text><g transform=\"translate(270,110)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"16.5\" fill=\"#1d2733\"/><rect x=\"-14\" y=\"36.0\" width=\"28\" height=\"16.5\" fill=\"#f2b531\"/><rect x=\"-14\" y=\"52.0\" width=\"28\" height=\"16.5\" fill=\"#1d2733\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><path d=\"M-8,-6 L8,-6 L0,-18 Z\" fill=\"#1d2733\"/><path d=\"M-8,-6 L8,-6 L0,6 Z\" fill=\"#1d2733\"/></g><text x=\"270\" y=\"196\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">LESTE</text><text x=\"270\" y=\"210\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">base com base</text><g transform=\"translate(50,110)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"16.5\" fill=\"#f2b531\"/><rect x=\"-14\" y=\"36.0\" width=\"28\" height=\"16.5\" fill=\"#1d2733\"/><rect x=\"-14\" y=\"52.0\" width=\"28\" height=\"16.5\" fill=\"#f2b531\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><path d=\"M-8,-18 L8,-18 L0,-6 Z\" fill=\"#1d2733\"/><path d=\"M-8,6 L8,6 L0,-6 Z\" fill=\"#1d2733\"/></g><text x=\"50\" y=\"196\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">OESTE</text><text x=\"50\" y=\"210\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">ponta com ponta</text><text x=\"160\" y=\"298\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">passe pelo lado que dá nome à boia</text></svg>"}, {"t": "Perigo isolado, águas seguras e especial", "p": ["Perigo isolado: <b>preta e encarnada</b>, duas esferas pretas.", "Águas seguras: listras verticais <b>brancas e encarnadas</b>.", "Cardinais, perigo isolado e águas seguras: luz <b>branca</b>. Especial: amarela com <b>X amarelo</b>.", "Durante o dia, os sinais são identificados por <b>marca de tope, forma e cor</b>. Boia cega <b>não tem luz</b> (só é vista de dia).", "<b>Farol</b>: estrutura fixa com luz de alcance superior a 10 milhas.", "Achou sinalização danificada? Avise a <b>Capitania dos Portos</b>."], "f": "<svg viewBox=\"0 0 320 190\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><g transform=\"translate(60,30)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"16.5\" fill=\"#1d2733\"/><rect x=\"-14\" y=\"36.0\" width=\"28\" height=\"16.5\" fill=\"#cf2e3a\"/><rect x=\"-14\" y=\"52.0\" width=\"28\" height=\"16.5\" fill=\"#1d2733\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><circle cx=\"0\" cy=\"-2\" r=\"6\" fill=\"#1d2733\"/><circle cx=\"0\" cy=\"-16\" r=\"6\" fill=\"#1d2733\"/></g><g transform=\"translate(160,30)\"><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"#fff\"/><rect x=\"-14\" y=\"20\" width=\"3.5\" height=\"48\" fill=\"#cf2e3a\"/><rect x=\"-7\" y=\"20\" width=\"3.5\" height=\"48\" fill=\"#cf2e3a\"/><rect x=\"0\" y=\"20\" width=\"3.5\" height=\"48\" fill=\"#cf2e3a\"/><rect x=\"7\" y=\"20\" width=\"3.5\" height=\"48\" fill=\"#cf2e3a\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><circle cx=\"0\" cy=\"-2\" r=\"7\" fill=\"#cf2e3a\"/></g><g transform=\"translate(260,30)\"><rect x=\"-14\" y=\"20.0\" width=\"28\" height=\"48.5\" fill=\"#f2b531\"/><rect x=\"-14\" y=\"20\" width=\"28\" height=\"48\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"1.5\"/><line x1=\"0\" y1=\"20\" x2=\"0\" y2=\"6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M-26,72 q8,-5 16,0 t16,0 t16,0 t16,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2\"/><path d=\"M-7,-10 L7,4 M7,-10 L-7,4\" stroke=\"#f2b531\" stroke-width=\"4\"/></g><text x=\"60\" y=\"128\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">PERIGO ISOLADO</text><text x=\"60\" y=\"144\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">preta + faixa encarnada</text><text x=\"60\" y=\"158\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">2 esferas pretas</text><text x=\"60\" y=\"172\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">luz branca</text><text x=\"160\" y=\"128\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">ÁGUAS SEGURAS</text><text x=\"160\" y=\"144\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">listras verticais</text><text x=\"160\" y=\"158\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">brancas e encarnadas</text><text x=\"160\" y=\"172\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">luz branca</text><text x=\"260\" y=\"128\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">ESPECIAL</text><text x=\"260\" y=\"144\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">amarela</text><text x=\"260\" y=\"158\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">X amarelo no tope</text><text x=\"260\" y=\"172\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">luz amarela</text></svg>"}, {"t": "Hidrovias e rios", "p": ["Placa com <b>quadrado</b>: canal junto à margem. <b>H</b>: meio do canal. <b>Y</b>: bifurcação. <b>+</b>: perigo.", "Painel laranja com <b>R</b> preto: reduzir velocidade.", "Pilar de ponte com <b>triângulo vermelho</b>: tráfego à esquerda de quem sobe e à direita de quem desce o rio.", "Além dos sinais de canal, o balizamento fluvial tem símbolos de <b>perigo isolado</b> e <b>bifurcação</b>."], "f": "<svg viewBox=\"0 0 320 130\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><g transform=\"translate(34,20)\"><rect x=\"-24\" y=\"0\" width=\"48\" height=\"48\" rx=\"4\" fill=\"#fff\" stroke=\"var(--ink)\" stroke-width=\"2\"/><rect x=\"-11\" y=\"13\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"#1d2733\" stroke-width=\"5\"/></g><g transform=\"translate(97,20)\"><rect x=\"-24\" y=\"0\" width=\"48\" height=\"48\" rx=\"4\" fill=\"#fff\" stroke=\"var(--ink)\" stroke-width=\"2\"/><text x=\"0\" y=\"36\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"30\" fill=\"#1d2733\" text-anchor=\"middle\">H</text></g><g transform=\"translate(160,20)\"><rect x=\"-24\" y=\"0\" width=\"48\" height=\"48\" rx=\"4\" fill=\"#fff\" stroke=\"var(--ink)\" stroke-width=\"2\"/><text x=\"0\" y=\"36\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"30\" fill=\"#1d2733\" text-anchor=\"middle\">Y</text></g><g transform=\"translate(223,20)\"><rect x=\"-24\" y=\"0\" width=\"48\" height=\"48\" rx=\"4\" fill=\"#fff\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M0,10 V38 M-14,24 H14\" stroke=\"#1d2733\" stroke-width=\"6\"/></g><g transform=\"translate(286,20)\"><rect x=\"-24\" y=\"0\" width=\"48\" height=\"48\" rx=\"4\" fill=\"#f08a24\" stroke=\"var(--ink)\" stroke-width=\"2\"/><text x=\"0\" y=\"36\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"30\" fill=\"#1d2733\" text-anchor=\"middle\">R</text></g><text x=\"34\" y=\"86\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">canal junto</text><text x=\"34\" y=\"99\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">à margem</text><text x=\"97\" y=\"86\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">meio do</text><text x=\"97\" y=\"99\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">canal</text><text x=\"160\" y=\"86\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">bifurcação</text><text x=\"160\" y=\"99\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">de canal</text><text x=\"223\" y=\"86\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">perigo</text><text x=\"286\" y=\"86\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">reduzir</text><text x=\"286\" y=\"99\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--ink)\" text-anchor=\"middle\">velocidade</text></svg>"}]}, {"id": "inc", "nome": "Incêndio", "icone": "🔥", "cards": [{"t": "Triângulo do fogo", "p": ["Só há fogo com os três: <b>combustível, comburente (oxigênio) e temperatura de ignição</b>.", "Tirou um lado, o fogo apaga: <b>resfriamento</b> tira o calor, <b>abafamento</b> tira o oxigênio, <b>isolamento</b> tira o combustível.", "A água apaga por resfriamento porque <b>abaixa a temperatura</b> do material abaixo do ponto de ignição.", "Combustível com oxigênio próprio só apaga por <b>resfriamento</b>.", "O calor se transmite por <b>condução, convecção e irradiação</b>."], "f": "<svg viewBox=\"0 0 320 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><path d=\"M160,22 L280,190 L40,190 Z\" fill=\"#cf2e3a\" fill-opacity=\".12\" stroke=\"#cf2e3a\" stroke-width=\"4\" stroke-linejoin=\"round\"/><path d=\"M160,92 c18,22 22,36 10,54 c-4,-14 -10,-18 -14,-22 c2,14 -6,22 -12,26 c-10,-18 -2,-36 16,-58 z\" fill=\"#cf2e3a\"/><path d=\"M160,122 c8,10 8,20 2,26 c-6,-6 -10,-12 -2,-26z\" fill=\"#f2b531\"/><text x=\"78\" y=\"100\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"13\" fill=\"var(--ink)\" text-anchor=\"middle\" transform=\"rotate(-55 78 100)\">COMBUSTÍVEL</text><text x=\"242\" y=\"100\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"13\" fill=\"var(--ink)\" text-anchor=\"middle\" transform=\"rotate(55 242 100)\">COMBURENTE (O₂)</text><text x=\"160\" y=\"206\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"13\" fill=\"var(--ink)\" text-anchor=\"middle\">CALOR (temperatura de ignição)</text></svg>"}, {"t": "Classes e extintores", "p": ["<b>A</b> sólidos: triângulo verde, água. <b>B</b> líquidos: quadrado vermelho. <b>C</b> elétricos: círculo azul. <b>D</b> metais (limalha de alumínio, magnésio): estrela amarela.", "Água na gasolina não serve: a temperatura de ignição da gasolina é <b>menor</b> que a da água.", "Água salgada em classe C não: ela <b>conduz eletricidade</b>.", "Agentes extintores: <b>água, espuma, CO₂ e pó químico</b>.", "Extintor de espuma: <b>vire com a tampa para baixo</b> e mire na base das chamas."], "f": "<svg viewBox=\"0 0 320 170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><g transform=\"translate(45,14)\"><path d=\"M0,0 L32,56 L-32,56 Z\" fill=\"#0b8a4a\"/><text x=\"0\" y=\"48\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"24\" fill=\"#fff\" text-anchor=\"middle\">A</text></g><g transform=\"translate(120,14)\"><rect x=\"-28\" y=\"0\" width=\"56\" height=\"56\" fill=\"#cf2e3a\"/><text x=\"0\" y=\"38\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"24\" fill=\"#fff\" text-anchor=\"middle\">B</text></g><g transform=\"translate(200,14)\"><circle cx=\"0\" cy=\"28\" r=\"28\" fill=\"#2563a8\"/><text x=\"0\" y=\"37\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"24\" fill=\"#fff\" text-anchor=\"middle\">C</text></g><g transform=\"translate(278,14)\"><path d=\"M0,0 L8,20 L30,21 L13,35 L19,56 L0,44 L-19,56 L-13,35 L-30,21 L-8,20 Z\" fill=\"#f2b531\"/><text x=\"0\" y=\"38\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"18\" fill=\"#1d2733\" text-anchor=\"middle\">D</text></g><text x=\"45\" y=\"92\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">sólidos</text><text x=\"45\" y=\"106\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">madeira, papel,</text><text x=\"45\" y=\"119\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">tecido</text><text x=\"45\" y=\"136\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#0b8a4a\" text-anchor=\"middle\">ÁGUA</text><text x=\"120\" y=\"92\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">líquidos</text><text x=\"120\" y=\"106\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">gasolina, óleo</text><text x=\"120\" y=\"136\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"#cf2e3a\" text-anchor=\"middle\">ESPUMA, CO₂, PÓ</text><text x=\"200\" y=\"92\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">elétricos</text><text x=\"200\" y=\"106\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">energizados</text><text x=\"200\" y=\"136\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#2563a8\" text-anchor=\"middle\">CO₂, PÓ</text><text x=\"278\" y=\"92\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">metais</text><text x=\"278\" y=\"106\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">magnésio, sódio,</text><text x=\"278\" y=\"119\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">alumínio</text><text x=\"278\" y=\"136\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"#9a6a00\" text-anchor=\"middle\">PÓ ESPECIAL</text><text x=\"160\" y=\"162\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">símbolo do extintor e agente certo para cada classe</text></svg>"}, {"t": "A bordo", "p": ["Prioridade sempre: <b>salvar vidas</b>.", "O vento <b>propaga</b> o fogo. Fique do lado de onde o vento <b>está entrando</b>.", "O maior risco a bordo são os <b>combustíveis líquidos</b>. Guarde-os em compartimentos <b>abaixo da linha d'água</b> (gabarito).", "Sem extintor e com a parte elétrica desligada: <b>baldes d'água</b>.", "Sistema fixo de combate: <b>difusores fixos</b>."]}]}, {"id": "ps", "nome": "Primeiros socorros", "icone": "⛑️", "cards": [{"t": "Respiração e massagem", "p": ["Antes do boca a boca, veja se há <b>corpos estranhos na boca</b>.", "Vítima de barriga para cima, cabeça <b>inclinada para trás</b>.", "Coração parado depois do boca a boca: <b>massagem cardíaca</b>.", "Cadência pelo gabarito antigo: <b>70 por minuto</b>. Hoje se recomenda 100 a 120, mas na prova marque 70.", "Parada cardíaca e respiratória juntas, conforme a opção que aparecer: <b>8 massagens para 1 sopro</b> ou <b>10 massagens para 2 sopros</b>."]}, {"t": "Hemorragias", "p": ["Vê o sangue: hemorragia <b>externa</b>. Trauma sem sangue visível: pode ser <b>interna</b>, e aí <b>não dê água</b>.", "Perna sangrando: <b>eleve</b> acima do corpo.", "Torniquete só para hemorragias <b>muito grandes</b>. Afrouxe a cada <b>15 minutos</b> (exceto acima de amputação). Não cubra.", "Aqueça a vítima para <b>evitar o choque</b>."]}, {"t": "Queimaduras, fraturas e calor", "p": ["Grandes queimaduras: <b>nunca tire a roupa</b> grudada.", "Fratura exposta: <b>não recoloque o osso</b>. Proteja com pano limpo e imobilize.", "Imobilizar braço ou perna: <b>tala</b> com gaze, esparadrapo e algo rígido.", "Muito tempo sob sol forte: <b>insolação</b>.", "Enjoo: o vômito representa <b>grande perda de água</b>."]}]}, {"id": "sob", "nome": "Sobrevivência e salvatagem", "icone": "🦺", "cards": [{"t": "Coletes e boias", "p": ["O <b>colete</b> é obrigatório em todas as embarcações. Quantidade: pela <b>lotação no documento</b> do barco.", "Vestido obrigatório só em <b>moto aquática</b> (passageiros e condutor).", "Colete inflável: encha <b>já dentro da água</b>.", "Antes de sair, faça a <b>demonstração</b> do colete. Não use como encosto, travesseiro ou brinquedo.", "Iates: <b>duas boias</b> circulares ou ferradura."]}, {"t": "Balsa salva-vidas", "p": ["Balsa é salvatagem de <b>uso coletivo</b> (embarcação de sobrevivência).", "Revisão a cada 12 meses. Vida útil: <b>12 anos desde a fabricação</b>.", "Balsa classe II: exigida em <b>alto-mar</b>, em qualquer comprimento.", "Cabo da balsa rígida: corte só quando a embarcação <b>estiver afundando</b>.", "<b>Âncora flutuante</b>: reduz o efeito do vento e da corrente na deriva."], "f": "<svg viewBox=\"0 0 320 170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><path d=\"M0,70 q20,-6 40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2.5\"/><ellipse cx=\"90\" cy=\"66\" rx=\"56\" ry=\"14\" fill=\"#f08a24\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M48,62 Q90,10 132,62\" fill=\"#f08a24\" fill-opacity=\".85\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M146,70 Q190,96 236,112\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"2\"/><path d=\"M236,100 L276,90 L276,134 L236,124 Z\" fill=\"#8a94a6\" stroke=\"var(--ink)\" stroke-width=\"2\"/><text x=\"256\" y=\"152\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">âncora flutuante</text><text x=\"256\" y=\"166\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">reduz a deriva</text><text x=\"90\" y=\"112\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">balsa salva-vidas</text><text x=\"90\" y=\"126\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">uso coletivo</text><path d=\"M24,40 L60,40\" stroke=\"var(--muted)\" stroke-width=\"2\" marker-end=\"url(#ar3)\"/><defs><marker id=\"ar3\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 Z\" fill=\"var(--muted)\"/></marker></defs><text x=\"40\" y=\"30\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">vento</text></svg>"}, {"t": "Abandono e náufragos", "p": ["Antes de abandonar: <b>pedir socorro pelo VHF com a posição</b>.", "Saia com <b>roupas adequadas e material de salvatagem</b>.", "Viu alguém cair: grite <b>\"Homem ao mar por boreste\"</b> (ou bombordo).", "O mais importante para sobreviver é o <b>estado psicológico</b>. Nunca beba <b>água salgada</b>; a desidratação é o maior problema.", "Na água fria: fique calmo, não se agite. Com colete, posição <b>HELP</b> (joelhos encolhidos).", "Socorrer pessoas é obrigatório; salvar <b>bens materiais</b> fica a critério do comandante."]}]}, {"id": "man", "nome": "Manobra, fundeio e atracação", "icone": "🧭", "cards": [{"t": "Leme e hélice", "p": ["Timão para boreste: o leme vai para <b>boreste</b>, a popa vai para bombordo e a proa vai para boreste.", "A propulsão mais comum é o <b>giro do hélice</b> (peça com pás que movimenta o barco girando).", "Hélice de passo direito: o gabarito responde <b>\"boreste lentamente\"</b> nas três versões da pergunta.", "<b>Curva de Boutakow</b>: volta exatamente sobre a própria esteira (homem ao mar). <b>Curva de giro padrão</b>: leme e velocidade padrão.", "Mar ruim: <b>acelere na subida</b> da onda e desacelere antes da descida.", "<b>Capa</b>: proa ao vento, pouco seguimento, para aguentar o mau tempo."]}, {"t": "Atracar e desatracar", "p": ["Corrente paralela ao cais: aproxime <b>contra a corrente, a 30°</b>.", "Vento ou corrente perpendicular, chegando a barlavento: venha <b>paralelo ao cais, com pouco seguimento</b>.", "Corrente de proa: aguentam <b>lançante de proa e espringue de popa</b>. Para sair, folgue <b>primeiro os cabos de vante</b>.", "Cabos principais: <b>lançantes, espringues e traveses</b>. Com grande amplitude de maré, deixe alguém cuidando das espias.", "Desatracar com o ferro: âncora no bordo <b>oposto ao cais</b>, folgando os cabos e recolhendo a amarra."], "f": "<svg viewBox=\"0 0 320 215\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><rect x=\"10\" y=\"150\" width=\"300\" height=\"26\" fill=\"#b9b2a2\"/><text x=\"160\" y=\"168\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#3b352a\" text-anchor=\"middle\">CAIS</text><path d=\"M70,90 L230,90 C262,90 286,104 296,112 C286,120 262,134 230,134 L70,134 Z\" fill=\"var(--card)\" stroke=\"var(--ink)\" stroke-width=\"2.5\"/><text x=\"284\" y=\"84\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">proa</text><text x=\"64\" y=\"84\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"end\">popa</text><line x1=\"284\" y1=\"124\" x2=\"312\" y2=\"150\" stroke=\"#c8643a\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"240\" y1=\"134\" x2=\"190\" y2=\"150\" stroke=\"#2563a8\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"160\" y1=\"134\" x2=\"160\" y2=\"150\" stroke=\"#0b8a4a\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"100\" y1=\"134\" x2=\"150\" y2=\"150\" stroke=\"#2563a8\" stroke-width=\"3\" stroke-linecap=\"round\"/><line x1=\"76\" y1=\"134\" x2=\"24\" y2=\"150\" stroke=\"#c8643a\" stroke-width=\"3\" stroke-linecap=\"round\"/><text x=\"316\" y=\"192\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"#c8643a\" text-anchor=\"end\">lançante de proa</text><text x=\"226\" y=\"208\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"#2563a8\" text-anchor=\"middle\">espringue de proa</text><text x=\"4\" y=\"192\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"#c8643a\" text-anchor=\"start\">lançante de popa</text><text x=\"96\" y=\"208\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"#2563a8\" text-anchor=\"middle\">espringue de popa</text><text x=\"160\" y=\"52\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#0b8a4a\" text-anchor=\"middle\">través: perpendicular ao cais (verde)</text><text x=\"160\" y=\"30\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">corrente de proa: aguentam lançante de proa + espringue de popa</text></svg>"}, {"t": "Fundeio", "p": ["Observe <b>vento, corrente e maré</b>; alinhe-se ao que predominar.", "Para fundear: dê máquina atrás e largue a âncora quando o barco estiver <b>caindo a ré</b>. Desligue o motor só quando o ferro <b>unhar</b>.", "Bom fundeadouro: abrigado, profundidade adequada, <b>boa tença</b> e apoio. Âncora Danforth: evite <b>areia dura</b> (gabarito).", "Para suspender: recolha com máquina devagar adiante se a amarra estiver tesada para vante.", "Boia de marina presa por <b>poita</b> no fundo. Prender o barco numa boia é <b>pegar a boia</b>.", "Nó de <b>escota</b>: une cabos de bitolas diferentes."], "f": "<svg viewBox=\"0 0 320 170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><path d=\"M0,40 q20,-6 40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0 t40,0\" fill=\"none\" stroke=\"#2563a8\" stroke-width=\"2.5\"/><rect x=\"0\" y=\"146\" width=\"320\" height=\"24\" fill=\"#cdbf9c\"/><path d=\"M30,30 l40,0 l-6,12 l-28,0 z\" fill=\"var(--ink)\"/><path d=\"M64,40 Q150,150 290,146\" fill=\"none\" stroke=\"var(--ink)\" stroke-width=\"3\" stroke-dasharray=\"6 4\"/><path d=\"M282,140 l14,6 l-14,4 z\" fill=\"var(--ink)\"/><line x1=\"20\" y1=\"40\" x2=\"20\" y2=\"146\" stroke=\"#2563a8\" stroke-width=\"1.5\"/><text x=\"12\" y=\"98\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"#2563a8\" text-anchor=\"middle\" transform=\"rotate(-90 12 98)\">profundidade</text><text x=\"190\" y=\"90\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"var(--ink)\" text-anchor=\"middle\">amarra = 3 × profundidade</text><text x=\"190\" y=\"108\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"12\" fill=\"#cf2e3a\" text-anchor=\"middle\">mau tempo ou fundeio longo: 5 ×</text></svg>"}]}, {"id": "met", "nome": "Meteorologia", "icone": "🌦️", "cards": [{"t": "Ventos e brisas", "p": ["<b>Brisa marítima</b>: à tarde, do mar para a terra. <b>Terrestre</b>: à noite, da terra para o mar.", "Gabarito: o principal fenômeno para a previsão é a <b>direção do vento</b>.", "Estado do mar pela força do vento: escala <b>Beaufort</b>.", "<b>Buys-Ballot</b>: de frente para o vento, a baixa pressão fica à direita no hemisfério norte e à esquerda no sul."], "f": "<svg viewBox=\"0 0 320 200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\"><defs><marker id=\"ab\" viewBox=\"0 0 10 10\" refX=\"5\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#2563a8\"/></marker></defs><rect x=\"4\" y=\"96\" width=\"70\" height=\"40\" fill=\"#2563a8\" fill-opacity=\".35\"/><rect x=\"74\" y=\"88\" width=\"80\" height=\"48\" fill=\"#b98e5a\"/><circle cx=\"34\" cy=\"26\" r=\"11\" fill=\"#f2b531\"/><path d=\"M44,70 L124,70\" stroke=\"#2563a8\" stroke-width=\"4\" marker-end=\"url(#ab)\"/><text x=\"39\" y=\"154\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">mar</text><text x=\"114\" y=\"154\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">terra</text><rect x=\"166\" y=\"96\" width=\"70\" height=\"40\" fill=\"#2563a8\" fill-opacity=\".35\"/><rect x=\"236\" y=\"88\" width=\"80\" height=\"48\" fill=\"#b98e5a\"/><circle cx=\"196\" cy=\"26\" r=\"10\" fill=\"#8a94a6\"/><circle cx=\"202\" cy=\"22\" r=\"9\" fill=\"var(--card)\"/><path d=\"M286,70 L206,70\" stroke=\"#2563a8\" stroke-width=\"4\" marker-end=\"url(#ab)\"/><text x=\"201\" y=\"154\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">mar</text><text x=\"276\" y=\"154\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--muted)\" text-anchor=\"middle\">terra</text><text x=\"79\" y=\"176\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">BRISA MARÍTIMA</text><text x=\"79\" y=\"192\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">tarde · do mar para a terra</text><text x=\"241\" y=\"176\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"11\" fill=\"var(--ink)\" text-anchor=\"middle\">BRISA TERRESTRE</text><text x=\"241\" y=\"192\" font-family=\"Nunito,sans-serif\" font-weight=\"800\" font-size=\"10\" fill=\"var(--muted)\" text-anchor=\"middle\">noite · da terra para o mar</text></svg>"}, {"t": "Pressão, ar e clima", "p": ["Pressão <b>subindo</b>: tempo bom ou melhorando. Caindo: piora.", "A atmosfera é principalmente <b>nitrogênio</b>.", "O clima de cada região muda ao longo do ano pelo <b>ângulo de incidência do Sol</b>.", "Nevoeiro formado pelo ar subindo um terreno elevado: <b>orográfico</b>.", "Na carta sinótica, o gabarito põe as praias de SP e RJ na área <b>Charlie</b>."]}]}, {"id": "leg", "nome": "Legislação (NORMAM e RLESTA)", "icone": "📜", "cards": [{"t": "Habilitações", "p": ["<b>Amador</b>: habilitado para esporte e recreio, sem caráter profissional.", "<b>Veleiro</b>: só vela, águas interiores. <b>Motonauta</b>: moto aquática, 18 anos, treino prático e prova na Capitania.", "<b>Arrais</b>: águas interiores. <b>Mestre</b>: navegação costeira (inclusive Brasil–Uruguai). <b>Capitão</b>: oceânica.", "Timoneiro manobra o leme por ordem do comandante; <b>não é necessariamente o comandante</b>. A disciplina a bordo é responsabilidade do <b>comandante</b>."]}, {"t": "Documentos e regras", "p": ["A bordo: Título de Inscrição + <b>CHA, seguro DPEM e RG</b>.", "Vistoria em construção, modificação ou transformação: <b>vistoria inicial</b>.", "Esporte e recreio <b>não pode</b> ter atividade comercial.", "Bandeira Nacional dispensada em <b>embarcações miúdas</b>. Miúda: até 5 m, convés aberto, sem cabine habitável, motor de popa até 50 HP.", "Moto aquática só vale como exceção no <b>salvamento</b>. Banana-boat: até <b>5 pessoas</b>.", "Motor perto das praias: só a partir de <b>200 m</b> da linha de base. Entrada na água pela extremidade da praia ou local definido pela <b>Prefeitura</b>."]}, {"t": "Infrações", "p": ["Infração mais grave a bordo: <b>excesso de passageiros</b>.", "Apreensão independente de multa: <b>menor sem habilitação</b> conduzindo. O barco vai para local definido pela <b>autoridade marítima</b>.", "Irregularidade não sanada no prazo: embarcação <b>leiloada ou incorporada à União</b>.", "Trafegar em área de banhistas: grupo D, suspensão da carteira por até <b>60 dias</b>.", "Pedido de reconsideração da multa: <b>5 dias úteis</b>."]}, {"t": "Tipos de navegação e pessoas", "p": ["<b>Mar aberto</b>: águas desabrigadas. <b>Cabotagem</b>: entre portos do Brasil (Rio–Belém). <b>Longo curso</b>: internacional. <b>Apoio marítimo</b>: plataformas de petróleo e minérios.", "<b>Passageiro</b>: transportado, sem trabalhar a bordo. <b>Profissional não-tripulante</b>: presta serviço eventual.", "<b>SOLAS</b>: convenção para a segurança da vida humana no mar."]}]}];
